import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry gelu_kernel(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 n
)
{
    .reg .pred %p<4>;
    .reg .f32  %f<20>;
    .reg .b32  %r<12>;
    .reg .b64  %rd<12>;

    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u32 %r1, [n];

    cvta.to.global.u64 %rd3, %rd1;
    cvta.to.global.u64 %rd4, %rd2;

    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.s32 %r5, %r2, %r3, %r4;   // idx

    mov.u32 %r6, %nctaid.x;
    mul.lo.s32 %r7, %r6, %r3;        // stride

LOOP_START:
    setp.ge.s32 %p1, %r5, %r1;
    @%p1 bra LOOP_END;

    mul.wide.s32 %rd5, %r5, 4;
    add.s64 %rd6, %rd3, %rd5;
    add.s64 %rd7, %rd4, %rd5;

    ld.global.f32 %f1, [%rd6];       // x

    mul.f32 %f2, %f1, %f1;           // x*x
    mul.f32 %f3, %f2, %f1;           // x^3

    mov.f32 %f4, 0f3D370765;         // 0.044715
    fma.rn.f32 %f5, %f4, %f3, %f1;   // x + 0.044715*x^3

    mov.f32 %f6, 0f3F4C422A;         // sqrt(2/pi) = 0.7978845608028654
    mul.f32 %f7, %f5, %f6;           // inner

    tanh.approx.f32 %f8, %f7;        // tanh(inner)

    mov.f32 %f9, 0f3F800000;         // 1.0
    add.f32 %f10, %f8, %f9;          // 1 + tanh

    mov.f32 %f11, 0f3F000000;        // 0.5
    mul.f32 %f12, %f11, %f1;         // 0.5*x
    mul.f32 %f13, %f12, %f10;        // result

    st.global.f32 [%rd7], %f13;

    add.s32 %r5, %r5, %r7;
    bra LOOP_START;

LOOP_END:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("gelu_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x):
        assert x.is_cuda and x.dtype == torch.float32
        x = x.contiguous()
        out = torch.empty_like(x)

        n = x.numel()
        module = _get_ptx_module()

        block_x = 256
        grid_x = (n + block_x - 1) // block_x
        # Cap grid size and rely on grid-stride loop for full coverage.
        max_grid_x = 65535
        if grid_x > max_grid_x:
            grid_x = max_grid_x

        module.launch(
            "gelu_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, out, i32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return out

